import data from "./moves.json";
import { smart } from "./typo.mjs";
import type { Theme } from "./clip";

// Generated by scripts/site/moves.mjs from prompts/moves. Server code only: the rendered markdown
// is about 380 KB, so a client component gets a MoveCard list, never this module's MOVES.

export type Handle = { influence: number; speed: number };
export type Ease = { name: string; out: Handle; into: Handle };
export type Move = {
  duration: number | null;
  name: string;
  title: string;
  group: string | null;
  look: string;
  use: string;
  useWhen: string;
  jobs: string[];
  sound: string | null;
  snippet: string;
  clipHash: string | null;
  theme: Theme;
  variant: Theme | null;
  variantHash: string | null;
  eases: Ease[];
  published: string;
  modified: string;
  clipDate: string | null;
  useHtml: string;
  codeHtml: string;
  soundHtml: string;
  notesHtml: string;
};
export type Facet = { id: string; label: string };
export type Job = Facet & { moves: string[] };
export type MoveCard = Pick<Move, "name" | "title" | "group" | "look" | "use" | "jobs" | "clipHash" | "theme" | "variant" | "variantHash" | "duration">;

// The data stays ASCII (llms.txt and the .md copies read it); the pages read it through the typographic transform.
const typeset = (m: Move): Move => ({
  ...m,
  title: smart(m.title),
  use: smart(m.use),
  useWhen: smart(m.useWhen),
  sound: m.sound && smart(m.sound),
});

export const MOVES = (data.moves as Move[]).map(typeset);
export const GROUPS = data.groups as Facet[];
export const LOOKS = data.looks as string[];
export const JOBS = (data.jobs as Job[]).map((j) => ({ ...j, label: smart(j.label) }));
export const MOVES_TITLE = `${MOVES.length} CSS video components for AI-agent video | vawe`;
export const MOVES_DESCRIPTION = `${MOVES.length} proven motion video components, each a clip and the markdown an agent copies: when to use it, the CSS and Web Animations snippet, the notes and the sound cue.`;
export const MOVES_INTRO = `Each video component is one markdown file with a short clip, the CSS and Web Animations snippet, notes on when to use it and a sound note. The ${MOVES.length} are sorted into ${GROUPS.length} groups, from revealing a title to ending a film, and the filters below narrow them by look or by job.`;
export const FEATURED = data.featured as string[];

// The gallery order: by category, then the order within it. Card numbers and prev/next follow it.
export const NUMBERED = GROUPS.flatMap((g) => MOVES.filter((m) => m.group === g.id));

export const moveByName = (name: string) => MOVES.find((m) => m.name === name) ?? null;
export const groupLabel = (id: string | null) => GROUPS.find((g) => g.id === id)?.label ?? "";

export const toCard = ({ name, title, group, look, use, jobs, clipHash, theme, variant, variantHash, duration }: Move): MoveCard => ({ name, title, group, look, use, jobs, clipHash, theme, variant, variantHash, duration });

export { clip } from "./clip";
